136	function ConnectDialog({ config, open, onOpenChange }: ConnectDialogProps) {
137	  const [value, setValue] = useState("");
138	  const connectIntegration = useConnectIntegration();
139	
140	  const handleSave = async () => {
141	    const trimmed = value.trim();
142	    if (!trimmed) return;
143	
144	    try {
145	      await connectIntegration.mutateAsync({
146	        provider: config.id,
147	        trackingId: trimmed,
148	      });
149	      toast.success("Connected successfully");
150	      setValue("");
151	      onOpenChange(false);
152	    } catch {
153	      toast.error("Failed to connect. Please check your ID and try again.");
154	    }
155	  };
156	
157	  const handleOpenChange = (nextOpen: boolean) => {
158	    if (!nextOpen) setValue("");
159	    onOpenChange(nextOpen);
160	  };
161	
162	  return (
163	    <Dialog open={open} onOpenChange={handleOpenChange}>
164	      <DialogContent className="sm:max-w-md">
165	        <DialogHeader>
166	          <DialogTitle>Connect {config.name}</DialogTitle>
167	        </DialogHeader>
168	
169	        <div className="space-y-3 py-2">
170	          <div className="space-y-1.5">
