172	            <Input
173	              id="tracking-id"
174	              placeholder={config.inputPlaceholder}
175	              value={value}
176	              onChange={(e) => setValue(e.target.value)}
177	              onKeyDown={(e) => {
178	                if (e.key === "Enter") handleSave();
179	              }}
180	              disabled={connectIntegration.isPending}
181	              autoFocus
182	            />
183	            <p className="text-xs text-muted-foreground">{config.inputHint}</p>
184	          </div>
185	        </div>
186	
187	        <DialogFooter className="gap-2 sm:gap-0">
