438	      // Results are saved — don't fail the whole scan
439	    }
440	
441	    // ── 11. Send scan complete email (fire-and-forget) ─────────────
442	    try {
443	      // Fetch user profile for name and email
444	      const [profileRes, emailRes] = await Promise.all([
445	        supabase
446	          .from("profiles")
447	          .select("full_name, company_name")
448	          .eq("id", user.id)
449	          .single(),
450	        supabase.auth.admin.getUserById(user.id),
451	      ]);
452	
453	      const userName = profileRes.data?.full_name ?? "there";
454	      const userEmail = emailRes.data?.user?.email;
455	
456	      if (userEmail) {
457	        await supabase.functions.invoke("send-email", {
458	          body: {
459	            type: "scan_complete",
460	            to: userEmail,
461	            data: {
462	              name: userName,
463	              url,
464	              score: scoring.overall_score,
465	              scan_id: scanId,
466	              critical_count: scoring.critical_issues,
467	              quick_wins: scoring.quick_wins,
468	            },
469	          },
470	        });
471	      }
472	    } catch (emailErr) {
473	      // Non-critical: never fail a scan because the notification email failed
474	      console.warn("Scan complete email failed (non-fatal):", emailErr);
475	    }
476	
477	    return corsResponse({ scan_id: scanId, overall_score: scoring.overall_score });
478	  } catch (error) {
479	    const msg = error instanceof Error ? error.message : "Unexpected error during scan";
480	    console.error("Unexpected scan error:", error);
481	    await failScan(msg);
482	    return corsResponse({ error: "Scan failed due to an unexpected error" }, 500);
483	  }
