889	function parsePageSpeedData(psData: Record<string, unknown>): PageSpeedResult {
890	  const lh = (psData as { lighthouseResult?: LighthouseResult })?.lighthouseResult;
891	  const audits = lh?.audits ?? {};
892	  const categories = lh?.categories ?? {};
893	
894	  const performanceScore = Math.round(
895	    (categories.performance?.score ?? 0.5) * 100,
896	  );
897	
898	  // Extract Core Web Vitals in milliseconds
899	  const lcpMs: number = audits["largest-contentful-paint"]?.numericValue ?? 0;
900	  const clsVal: number = audits["cumulative-layout-shift"]?.numericValue ?? 0;
901	  const tbtMs: number = audits["total-blocking-time"]?.numericValue ?? 0;
902	  const fcpMs: number = audits["first-contentful-paint"]?.numericValue ?? 0;
903	  const ttfbMs: number = audits["server-response-time"]?.numericValue ?? 0;
904	  const speedIndexMs: number = audits["speed-index"]?.numericValue ?? 0;
905	
906	  const findings: Finding[] = [];
907	
908	  // LCP findings
909	  if (lcpMs > 0) {
910	    const lcpSec = (lcpMs / 1000).toFixed(1);
911	    if (lcpMs > 4000) {
912	      findings.push(buildPerfFinding(
913	        "f_pp_lcp",
914	        `LCP (Largest Contentful Paint) is critically slow at ${lcpSec}s`,
915	        "critical",
916	        `Your LCP is ${lcpSec}s — Google classifies anything above 4.0s as 'Poor'. This is the single biggest drag on both your SEO rankings and conversion rate. Users see a blank/incomplete page for ${lcpSec} seconds before your primary content renders.`,
917	        "Identify your LCP element (usually the hero image). Serve it in WebP format, use <link rel='preload'> in <head>, and ensure it's not blocked by render-blocking resources.",
918	        `1. Add <link rel="preload" as="image" href="hero.webp"> to <head>\n2. Convert hero to WebP (60-80% smaller than PNG/JPG)\n3. Set explicit width/height on the hero element to prevent layout shift\n4. Remove any render-blocking CSS above the fold`,
919	        false,
920	        "moderate",
921	        "2-5% conversion lift",
922	        "Technical",
923	      ));
924	    } else if (lcpMs > 2500) {
925	      findings.push(buildPerfFinding(
926	        "f_pp_lcp",
927	        `LCP needs improvement at ${lcpSec}s (good threshold: 2.5s)`,
928	        "warning",
929	        `Your LCP is ${lcpSec}s — Google's 'Needs Improvement' range is 2.5-4.0s. Your hero content takes ${lcpSec} seconds to appear, which increases bounce rate by approximately ${Math.round((lcpMs - 2500) / 100)}%.`,
930	        "Optimize your LCP element: convert to WebP, add preload hint, and eliminate render-blocking resources above the fold.",
931	        `Add to <head>: <link rel="preload" as="image" href="hero.webp">\nConvert hero image to WebP format — typical savings: 60-80% file size reduction`,
932	        false,
933	        "moderate",
934	        "1-2% conversion lift",
935	        "Technical",
936	      ));
937	    } else {
938	      findings.push(buildPerfFinding(
939	        "f_pp_lcp",
940	        `Good LCP score: ${lcpSec}s (under 2.5s threshold)`,
941	        "passed",
942	        `Your LCP of ${lcpSec}s is within Google's 'Good' range (< 2.5s). Primary content renders quickly, minimizing abandonment from slow loads.`,
943	        "Maintain this performance. Monitor after adding new hero images or scripts.",
944	        "No changes needed — LCP is performing well.",
945	        false,
946	        "quick",
947	        "0%",
948	        "Technical",
949	      ));
950	    }
951	  }
952	
953	  // CLS findings
954	  if (clsVal > 0) {
955	    if (clsVal > 0.25) {
956	      findings.push(buildPerfFinding(
957	        "f_pp_cls",
958	        `CLS (Cumulative Layout Shift) is critically high at ${clsVal.toFixed(3)}`,
959	        "critical",
