961	        "Add explicit width and height attributes to all images and iframes. Reserve space for dynamically injected content (ads, embeds, fonts).",
962	        `1. Add width/height to all images: <img width="800" height="450" ...>\n2. Add font-display: swap to @font-face declarations\n3. Reserve space for ads: min-height: 250px on ad containers\n4. Avoid inserting content above existing content on page load`,
963	        false,
964	        "moderate",
965	        "1-3% conversion lift",
966	        "Technical",
967	      ));
968	    } else if (clsVal > 0.1) {
969	      findings.push(buildPerfFinding(
