/**
 * slack-oauth — Edge Function
 *
 * Handles the OAuth 2.0 callback from Slack after user authorizes the app.
 * Exchanges the one-time code for an access token and stores it in the
 * integrations table, then redirects the user back to the app.
 *
 * Flow:
 *   User clicks "Connect Slack" → redirected to Slack OAuth page
 *   → Slack redirects to this function with ?code=xxx&state=user_id
 *   → Function exchanges code for access_token
 *   → Stores integration row in Supabase
 *   → Redirects user to /integrations?slack=connected
 *
 * Required env vars:
 *   SLACK_CLIENT_ID        — Slack app client ID
 *   SLACK_CLIENT_SECRET    — Slack app client secret
 *   SUPABASE_URL           — Supabase project URL (auto-injected by Supabase)
 *   SUPABASE_SERVICE_ROLE_KEY — Service role key (auto-injected by Supabase)
 *   SITE_URL               — Frontend URL, e.g. https://app.convertscan.com
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS headers ──────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
};

// ── Slack OAuth token response shape ─────────────────────────

interface SlackOAuthResponse {
  ok: boolean;
  error?: string;
  access_token?: string;
  token_type?: string;
  scope?: string;
  bot_user_id?: string;
  app_id?: string;
  team?: { id: string; name: string };
  authed_user?: { id: string };
  incoming_webhook?: {
    channel: string;
    channel_id: string;
    configuration_url: string;
    url: string;
  };
}

// ── Handler ───────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  const siteUrl = Deno.env.get("SITE_URL") ?? "http://localhost:8080";
  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const clientId = Deno.env.get("SLACK_CLIENT_ID") ?? "";
  const clientSecret = Deno.env.get("SLACK_CLIENT_SECRET") ?? "";

  // Only accept GET (Slack sends a redirect)
  if (req.method !== "GET") {
    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
  }

  const reqUrl = new URL(req.url);
  const code = reqUrl.searchParams.get("code");
  const state = reqUrl.searchParams.get("state"); // user_id passed as state

  // Validate required params
  if (!code || !state) {
    console.error("slack-oauth: missing code or state param");
    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
  }

  // Exchange code for access token
  const redirectUri = `${supabaseUrl}/functions/v1/slack-oauth`;

  let oauthData: SlackOAuthResponse;
  try {
    const tokenRes = await fetch("https://slack.com/api/oauth.v2.access", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        client_id: clientId,
        client_secret: clientSecret,
        code,
        redirect_uri: redirectUri,
      }),
    });

    if (!tokenRes.ok) {
      console.error("slack-oauth: Slack API HTTP error", tokenRes.status);
      return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
    }

    oauthData = (await tokenRes.json()) as SlackOAuthResponse;
  } catch (err) {
    console.error("slack-oauth: token exchange fetch failed", err);
    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
  }

  if (!oauthData.ok || !oauthData.access_token) {
    console.error("slack-oauth: Slack returned error:", oauthData.error);
    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
  }

  // Persist integration to Supabase using service role (bypasses RLS)
  const supabase = createClient(supabaseUrl, serviceRoleKey);

  const metadata: Record<string, unknown> = {
    team_id: oauthData.team?.id ?? null,
    team_name: oauthData.team?.name ?? null,
    scope: oauthData.scope ?? null,
    bot_user_id: oauthData.bot_user_id ?? null,
    app_id: oauthData.app_id ?? null,
    // Store incoming webhook channel if present (incoming-webhook scope)
    channel_id: oauthData.incoming_webhook?.channel_id ?? null,
    channel: oauthData.incoming_webhook?.channel ?? null,
    webhook_url: oauthData.incoming_webhook?.url ?? null,
  };

  const { error: upsertError } = await supabase
    .from("integrations")
    .upsert(
      {
        user_id: state,
        provider: "slack",
        access_token: oauthData.access_token,
        is_active: true,
        metadata,
      },
      { onConflict: "user_id,provider" },
    );

  if (upsertError) {
    console.error("slack-oauth: failed to upsert integration row", upsertError);
    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
  }

  return Response.redirect(`${siteUrl}/integrations?slack=connected`, 302);
});

/**
 * slack-notify — Edge Function (internal)
 *
 * Posts a scan-complete notification to the user's connected Slack workspace.
 * Called fire-and-forget from analyze-url after a scan completes.
 * Never throws to the caller — all errors are logged and swallowed.
 *
 * Required env vars:
 *   SUPABASE_URL              — auto-injected
 *   SUPABASE_SERVICE_ROLE_KEY — auto-injected
 *   SITE_URL                  — e.g. https://app.convertscan.com
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS ──────────────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── Request body shape ────────────────────────────────────────

interface TopFinding {
  title: string;
  severity: string;
}

interface NotifyPayload {
  user_id: string;
  scan_id: string;
  url: string;
  overall_score: number;
  top_findings: TopFinding[];
}

// ── Slack block types (minimal subset we need) ────────────────

interface SlackTextObject {
  type: "plain_text" | "mrkdwn";
  text: string;
  emoji?: boolean;
}

interface SlackHeaderBlock {
  type: "header";
  text: SlackTextObject;
}

interface SlackSectionBlock {
  type: "section";
  text: SlackTextObject;
  fields?: SlackTextObject[];
}

interface SlackDividerBlock {
  type: "divider";
}

type SlackBlock = SlackHeaderBlock | SlackSectionBlock | SlackDividerBlock;

interface SlackChatPostMessagePayload {
  channel: string;
  blocks: SlackBlock[];
  text: string; // fallback for notifications
}

// ── Integration metadata shape ────────────────────────────────

interface SlackIntegrationMetadata {
  channel_id?: string | null;
  channel?: string | null;
  team_name?: string | null;
  [key: string]: unknown;
}

// ── Score → emoji ─────────────────────────────────────────────

function scoreEmoji(score: number): string {
  if (score >= 70) return ":large_green_circle:";
  if (score >= 40) return ":large_yellow_circle:";
  return ":red_circle:";
}

// ── Severity → emoji ──────────────────────────────────────────

function severityEmoji(severity: string): string {
  switch (severity) {
    case "critical": return ":rotating_light:";
    case "warning": return ":warning:";
    case "passed": return ":white_check_mark:";
    default: return ":information_source:";
  }
}

// ── Handler ───────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  // Parse payload
  let payload: NotifyPayload;
  try {
    payload = (await req.json()) as NotifyPayload;
  } catch {
    return jsonResponse({ error: "Invalid JSON body" }, 400);
  }

  const { user_id, scan_id, url, overall_score, top_findings } = payload;

  if (!user_id || !scan_id || !url || typeof overall_score !== "number") {
    return jsonResponse({ error: "Missing required fields" }, 400);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const siteUrl = Deno.env.get("SITE_URL") ?? "https://app.convertscan.com";

  const supabase = createClient(supabaseUrl, serviceRoleKey);

  // Fetch the user's Slack integration
  const { data: integration, error: fetchError } = await supabase
    .from("integrations")
    .select("access_token, is_active, metadata")
    .eq("user_id", user_id)
    .eq("provider", "slack")
    .eq("is_active", true)
    .maybeSingle();

  if (fetchError) {
    console.warn("slack-notify: failed to fetch integration", fetchError);
    return jsonResponse({ skipped: true, reason: "db_error" });
  }

  if (!integration?.access_token) {
    // No active Slack integration — silent no-op
    return jsonResponse({ skipped: true, reason: "no_integration" });
  }

  const accessToken = integration.access_token as string;
  const metadata = (integration.metadata ?? {}) as SlackIntegrationMetadata;

  // Determine channel: prefer stored channel_id, fall back to default (#general)
  const channel = (metadata.channel_id as string | null | undefined) ?? "#general";

  // Build the report URL
  const reportUrl = `${siteUrl}/audit/${scan_id}`;
  const scoreLabel = `${scoreEmoji(overall_score)} *${overall_score}/100*`;

  // Build Slack blocks
  const blocks: SlackBlock[] = [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: "CRO Audit Complete",
        emoji: true,
      },
    },
    {
      type: "section",
      fields: [
        {
          type: "mrkdwn",
          text: `*Score*\n${scoreLabel}`,
        },
        {
          type: "mrkdwn",
          text: `*URL*\n<${url}|${url.length > 50 ? url.slice(0, 47) + "..." : url}>`,
        },
      ],
    },
  ];

  // Add top findings if present
  const findings = Array.isArray(top_findings) ? top_findings.slice(0, 3) : [];
  if (findings.length > 0) {
    const findingLines = findings
      .map((f) => `${severityEmoji(f.severity)} ${f.title}`)
      .join("\n");

    blocks.push({ type: "divider" });
    blocks.push({
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Top Findings*\n${findingLines}`,
      },
    });
  }

  blocks.push({ type: "divider" });
  blocks.push({
    type: "section",
    text: {
      type: "mrkdwn",
      text: `<${reportUrl}|View full report →>`,
    },
  });

  const slackPayload: SlackChatPostMessagePayload = {
    channel,
    blocks,
    text: `CRO Audit complete for ${url}: score ${overall_score}/100. View report: ${reportUrl}`,
  };

  // Post to Slack
  try {
    const slackRes = await fetch("https://slack.com/api/chat.postMessage", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${accessToken}`,
      },
      body: JSON.stringify(slackPayload),
    });

    if (!slackRes.ok) {
      console.warn("slack-notify: Slack HTTP error", slackRes.status);
      return jsonResponse({ sent: false, reason: "slack_http_error" });
    }

    interface SlackApiResponse {
      ok: boolean;
      error?: string;
    }

    const slackData = (await slackRes.json()) as SlackApiResponse;
    if (!slackData.ok) {
      console.warn("slack-notify: Slack API error:", slackData.error);
      // If token revoked, mark integration inactive
      if (slackData.error === "token_revoked" || slackData.error === "invalid_auth") {
        await supabase
          .from("integrations")
          .update({ is_active: false })
          .eq("user_id", user_id)
          .eq("provider", "slack");
      }
      return jsonResponse({ sent: false, reason: slackData.error });
    }
  } catch (err) {
    console.warn("slack-notify: fetch to Slack failed", err);
    return jsonResponse({ sent: false, reason: "network_error" });
  }

  return jsonResponse({ sent: true });
});

