  benefits: string[];
}

const SLACK_CONFIG: SlackIntegrationConfig = {
  name: "Slack",
  icon: MessageSquare,
  color: "text-purple-500",
  bg: "bg-purple-50",
  description:
    "Get instant scan results delivered to your Slack channels. Never miss a completed CRO audit.",
  benefits: [
    "Instant scan-complete notifications",
    "Score summary with top findings",
    "Direct link to full report",
  ],
};

