// ── Slack Integration Card ─────────────────────────────────────
// OAuth-based: connect redirects to Slack, no tracking-ID dialog needed.

interface SlackIntegrationCardProps {
  isConnected: boolean;
  isPro: boolean;
  userId: string;
}

function SlackIntegrationCard({
  isConnected,
  isPro,
  userId,
}: SlackIntegrationCardProps) {
  const Icon = SLACK_CONFIG.icon;
  const disconnectIntegration = useDisconnectIntegration();

  const slackClientId = import.meta.env.VITE_SLACK_CLIENT_ID as string | undefined;
  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string | undefined;

  const handleConnect = () => {
    if (!slackClientId || !supabaseUrl) {
      toast.error("Slack integration is not configured yet. Check back soon.");
      return;
    }
    const redirectUri = encodeURIComponent(`${supabaseUrl}/functions/v1/slack-oauth`);
    const scopes = encodeURIComponent("chat:write,chat:write.public");
    const oauthUrl = `https://slack.com/oauth/v2/authorize?client_id=${slackClientId}&scope=${scopes}&redirect_uri=${redirectUri}&state=${encodeURIComponent(userId)}`;
    window.location.href = oauthUrl;
  };

  const handleDisconnect = async () => {
    try {
      await disconnectIntegration.mutateAsync({ provider: "slack" });
      toast.success("Slack disconnected");
    } catch {
      toast.error("Failed to disconnect Slack");
    }
  };

  const handleSwitchChange = (checked: boolean) => {
    if (checked) {
      handleConnect();
    } else {
      void handleDisconnect();
    }
  };

  return (
    <Card className="border-border/50 shadow-soft">
      <CardContent className="p-6">
        {/* Header row */}
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            <div
              className={`flex h-14 w-14 items-center justify-center rounded-2xl ${SLACK_CONFIG.bg}`}
            >
              <Icon className={`h-6 w-6 ${SLACK_CONFIG.color}`} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-sm font-semibold text-foreground">
                  {SLACK_CONFIG.name}
                </h3>
                {!isPro && (
                  <Badge
                    variant="outline"
                    className="border-amber-200 bg-amber-50 text-amber-700 text-xs"
                  >
                    <Lock className="mr-1 h-2.5 w-2.5" />
                    Pro+
                  </Badge>
                )}
              </div>
              {isConnected ? (
                <Badge
                  variant="outline"
                  className="mt-1 border-green-200 bg-green-50 text-green-700 text-xs"
                >
                  <CheckCircle2 className="mr-1 h-3 w-3" />
                  Connected
                </Badge>
              ) : (
                <Badge
                  variant="outline"
                  className="mt-1 border-border text-muted-foreground text-xs"
                >
                  <Circle className="mr-1 h-3 w-3" />
                  Not connected
                </Badge>
              )}
            </div>
          </div>
          <Switch
            checked={isConnected}
            onCheckedChange={handleSwitchChange}
            disabled={!isPro || disconnectIntegration.isPending}
            aria-label="Toggle Slack connection"
          />
        </div>

        {/* Description */}
        <p className="mt-4 text-sm text-muted-foreground leading-relaxed">
          {SLACK_CONFIG.description}
        </p>

        {/* Benefits */}
        <div className="mt-4">
          <p className="mb-2 text-xs font-medium uppercase tracking-wider text-muted-foreground">
            What you'll get
          </p>
          <ul className="space-y-1.5">
            {SLACK_CONFIG.benefits.map((benefit) => (
              <li
                key={benefit}
                className="flex items-center gap-2 text-xs text-muted-foreground"
              >
                <span className="h-1 w-1 shrink-0 rounded-full bg-muted-foreground/50" />
                {benefit}
              </li>
            ))}
          </ul>
        </div>

        {/* Action button */}
        {!isPro ? (
          <Button
            size="sm"
            variant="outline"
            className="mt-4 w-full"
            disabled
          >
            <Lock className="mr-2 h-3.5 w-3.5" />
            Upgrade to Pro to Connect
          </Button>
        ) : isConnected ? (
          <Button
            variant="outline"
            size="sm"
            className="mt-4 w-full border-border/50 text-destructive hover:bg-destructive/5 hover:text-destructive"
            onClick={() => void handleDisconnect()}
            disabled={disconnectIntegration.isPending}
          >
            {disconnectIntegration.isPending ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Disconnecting…
              </>
            ) : (
              "Disconnect"
            )}
          </Button>
        ) : (
          <Button
            size="sm"
            className="mt-4 w-full"
            onClick={handleConnect}
          >
            Connect Slack
          </Button>
        )}
      </CardContent>
    </Card>
  );
}

